-- Generated from the canonical CSV dataset. Synthetic data only.

-- FK constraints are declared; enforcement is temporarily disabled during import so labelled anomalies remain auditable.

PRAGMA foreign_keys = OFF;

BEGIN TRANSACTION;

CREATE TABLE "suppliers" (
  "supplier_id" TEXT PRIMARY KEY,
  "supplier_name" TEXT,
  "supplier_code" TEXT,
  "supplier_contact_name" TEXT,
  "supplier_contact_email" TEXT,
  "supplier_contact_phone" TEXT,
  "supplier_status" TEXT,
  "risk_tier" TEXT,
  "region" TEXT,
  "lead_time_days" INTEGER,
  "reliability_score" REAL,
  "on_time_rate" REAL,
  "ack_rate" REAL,
  "on_time_promise_rate" REAL,
  "avg_slip_days" REAL,
  "preferred_carrier_id" TEXT,
  "default_currency" TEXT,
  "data_owner_role" TEXT,
  "created_at" TEXT,
  "updated_at" TEXT,
  FOREIGN KEY ("preferred_carrier_id") REFERENCES "carriers"("carrier_id")
);

CREATE TABLE "purchase_orders" (
  "po_id" TEXT PRIMARY KEY,
  "supplier_id" TEXT,
  "planner_actor_id" TEXT,
  "warehouse_id" TEXT,
  "carrier_id" TEXT,
  "order_date" TEXT,
  "required_delivery_date" TEXT,
  "response_due_at" TEXT,
  "currency" TEXT,
  "total_order_value" REAL,
  "status" TEXT,
  "created_by_role" TEXT,
  "created_by_actor_id" TEXT,
  "supplier_contact_email" TEXT,
  "version_no" INTEGER,
  "created_at" TEXT,
  "updated_at" TEXT,
  FOREIGN KEY ("supplier_id") REFERENCES "suppliers"("supplier_id"),
  FOREIGN KEY ("planner_actor_id") REFERENCES "actors"("actor_id"),
  FOREIGN KEY ("warehouse_id") REFERENCES "warehouses"("warehouse_id"),
  FOREIGN KEY ("carrier_id") REFERENCES "carriers"("carrier_id")
);

CREATE TABLE "po_lines" (
  "po_line_id" TEXT PRIMARY KEY,
  "po_id" TEXT,
  "line_no" INTEGER,
  "item_id" TEXT,
  "item_description" TEXT,
  "requested_qty" REAL,
  "ack_accepted_qty" REAL,
  "ack_rejected_qty" REAL,
  "promised_qty" REAL,
  "projected_qty" REAL,
  "uom" TEXT,
  "currency" TEXT,
  "unit_price" REAL,
  "acknowledged_unit_price" REAL,
  "promised_unit_price" REAL,
  "projected_unit_price" REAL,
  "line_total" REAL,
  "acknowledged_value" REAL,
  "promised_value" REAL,
  "projected_value" REAL,
  "required_date" TEXT,
  "status" TEXT,
  "created_at" TEXT,
  "updated_at" TEXT,
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("item_id") REFERENCES "items"("item_id")
);

CREATE TABLE "acknowledgements" (
  "ack_id" TEXT PRIMARY KEY,
  "po_id" TEXT,
  "supplier_id" TEXT,
  "po_line_id" TEXT,
  "revision_no" INTEGER,
  "status" TEXT,
  "lifecycle_state" TEXT,
  "acknowledged_at" TEXT,
  "response_due_at" TEXT,
  "requested_qty" REAL,
  "ack_accepted_qty" REAL,
  "ack_rejected_qty" REAL,
  "rejection_reason" TEXT,
  "promised_qty" REAL,
  "projected_qty" REAL,
  "requested_value" REAL,
  "acknowledged_value" REAL,
  "promised_value" REAL,
  "projected_value" REAL,
  "qty_delta_pct" REAL,
  "price_delta_pct" REAL,
  "date_slip_days" INTEGER,
  "supplier_note" TEXT,
  "superseded_by" TEXT,
  "created_at" TEXT,
  "created_by_role" TEXT,
  "created_by_actor_id" TEXT,
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "suppliers"("supplier_id")
);

CREATE TABLE "acknowledgement_lines" (
  "acknowledgement_line_id" TEXT PRIMARY KEY,
  "ack_id" TEXT,
  "po_id" TEXT,
  "po_line_id" TEXT,
  "revision_no" INTEGER,
  "status" TEXT,
  "requested_qty" TEXT,
  "accepted_qty" TEXT,
  "rejected_qty" TEXT,
  "rejected_reason" TEXT,
  "requested_unit_price" TEXT,
  "acknowledged_unit_price" TEXT,
  "qty_delta_pct" TEXT,
  "price_delta_pct" TEXT,
  "date_slip_days" TEXT,
  "response_timestamp" TEXT,
  "created_at" TEXT,
  "created_by_role" TEXT,
  "created_by_actor_id" TEXT,
  FOREIGN KEY ("ack_id") REFERENCES "acknowledgements"("ack_id"),
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id")
);

CREATE TABLE "promise_dates" (
  "promise_date_id" TEXT PRIMARY KEY,
  "ack_id" TEXT,
  "po_id" TEXT,
  "po_line_id" TEXT,
  "sequence_no" INTEGER,
  "revision_no" INTEGER,
  "promised_date" TEXT,
  "slip_days" INTEGER,
  "is_late" INTEGER,
  "promised_qty" REAL,
  "promise_confidence" TEXT,
  "ship_from_location" TEXT,
  "ship_from_warehouse_id" TEXT,
  "carrier_id" TEXT,
  "carrier_reference" TEXT,
  "carrier_operator_actor_id" TEXT,
  "prior_promised_date" TEXT,
  "effective_date" TEXT,
  "response_due_date" TEXT,
  "status" TEXT,
  "superseded_by" TEXT,
  "source" TEXT,
  "created_at" TEXT,
  "created_by_role" TEXT,
  "created_by_actor_id" TEXT,
  FOREIGN KEY ("ack_id") REFERENCES "acknowledgements"("ack_id"),
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id"),
  FOREIGN KEY ("carrier_id") REFERENCES "carriers"("carrier_id"),
  FOREIGN KEY ("ship_from_warehouse_id") REFERENCES "warehouses"("warehouse_id")
);

CREATE TABLE "change_requests" (
  "change_request_id" TEXT PRIMARY KEY,
  "po_id" TEXT,
  "supplier_id" TEXT,
  "po_line_id" TEXT,
  "request_type" TEXT,
  "change_type" TEXT,
  "old_value" TEXT,
  "new_value" TEXT,
  "delta" REAL,
  "delta_abs" REAL,
  "delta_pct" REAL,
  "required_approval_level" TEXT,
  "status" TEXT,
  "requested_at" TEXT,
  "effective_date" TEXT,
  "response_due_date" TEXT,
  "previous_qty" REAL,
  "requested_qty" REAL,
  "previous_unit_price" REAL,
  "requested_unit_price" REAL,
  "previous_promised_date" TEXT,
  "requested_promised_date" TEXT,
  "reason_code" TEXT,
  "reason_text" TEXT,
  "requested_by_role" TEXT,
  "requested_by_actor_id" TEXT,
  "created_at" TEXT,
  "updated_at" TEXT,
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "suppliers"("supplier_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id")
);

CREATE TABLE "approvals" (
  "approval_id" TEXT PRIMARY KEY,
  "change_request_id" TEXT,
  "approval_round" INTEGER,
  "approver_role" TEXT,
  "approval_level" TEXT,
  "approver_actor_id" TEXT,
  "status" TEXT,
  "requested_at" TEXT,
  "due_at" TEXT,
  "decided_at" TEXT,
  "decision_reason" TEXT,
  "comments" TEXT,
  "threshold_name" TEXT,
  "threshold_value" REAL,
  "created_at" TEXT,
  FOREIGN KEY ("change_request_id") REFERENCES "change_requests"("change_request_id"),
  FOREIGN KEY ("approver_actor_id") REFERENCES "actors"("actor_id")
);

CREATE TABLE "inventory_plans" (
  "inventory_plan_id" TEXT PRIMARY KEY,
  "po_id" TEXT,
  "po_line_id" TEXT,
  "plan_revision_no" INTEGER,
  "plan_version" INTEGER,
  "previous_version_id" TEXT,
  "source" TEXT,
  "is_effective" INTEGER,
  "projected_delivery_date" TEXT,
  "change_request_id" TEXT,
  "status" TEXT,
  "demand_qty" REAL,
  "requested_qty" REAL,
  "acknowledged_qty" REAL,
  "promised_qty" REAL,
  "projected_qty" REAL,
  "on_hand_qty" REAL,
  "reserved_qty" REAL,
  "planned_receipt_qty" REAL,
  "projected_available_qty" REAL,
  "projected_shortage_qty" REAL,
  "required_date" TEXT,
  "promised_date" TEXT,
  "plan_start_date" TEXT,
  "plan_end_date" TEXT,
  "planner_actor_id" TEXT,
  "approved_by_actor_id" TEXT,
  "effective_date" TEXT,
  "superseded_by" TEXT,
  "created_at" TEXT,
  "updated_at" TEXT,
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id"),
  FOREIGN KEY ("change_request_id") REFERENCES "change_requests"("change_request_id")
);

CREATE TABLE "production_orders" (
  "production_order_id" TEXT PRIMARY KEY,
  "inventory_plan_id" TEXT,
  "po_id" TEXT,
  "po_line_id" TEXT,
  "required_by_date" TEXT,
  "planned_start_date" TEXT,
  "status" TEXT,
  "at_risk" INTEGER,
  "shortfall_qty" REAL,
  "delay_days" INTEGER,
  "planned_qty" REAL,
  "released_qty" REAL,
  "completed_qty" REAL,
  "affected_material_qty" REAL,
  "priority" TEXT,
  "original_start_date" TEXT,
  "current_start_date" TEXT,
  "scheduled_end_date" TEXT,
  "actual_start_date" TEXT,
  "actual_end_date" TEXT,
  "schedule_shift_days" INTEGER,
  "owner_role" TEXT,
  "owner_actor_id" TEXT,
  "created_at" TEXT,
  "updated_at" TEXT,
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id"),
  FOREIGN KEY ("inventory_plan_id") REFERENCES "inventory_plans"("inventory_plan_id")
);

CREATE TABLE "production_order_line" (
  "production_order_id" TEXT,
  "po_line_id" TEXT,
  "allocated_quantity" TEXT,
  "allocated_uom" TEXT,
  "created_at" TEXT,
  PRIMARY KEY ("production_order_id", "po_line_id"),
  FOREIGN KEY ("production_order_id") REFERENCES "production_orders"("production_order_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id")
);

CREATE TABLE "production_order_impact" (
  "impact_id" TEXT PRIMARY KEY,
  "production_order_id" TEXT,
  "change_request_id" TEXT,
  "po_line_id" TEXT,
  "impact_type" TEXT,
  "severity" TEXT,
  "slip_days" INTEGER,
  "shortfall_pct" TEXT,
  "old_projected_delivery_date" TEXT,
  "new_projected_delivery_date" TEXT,
  "old_projected_qty" TEXT,
  "new_projected_qty" TEXT,
  "rescheduled_planned_start_date" TEXT,
  "created_at" TEXT,
  FOREIGN KEY ("production_order_id") REFERENCES "production_orders"("production_order_id"),
  FOREIGN KEY ("change_request_id") REFERENCES "change_requests"("change_request_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "po_lines"("po_line_id")
);

CREATE TABLE "notifications" (
  "notification_id" TEXT PRIMARY KEY,
  "not_id" TEXT,
  "not_type" TEXT,
  "severity" TEXT,
  "subject" TEXT,
  "related_entity_type" TEXT,
  "related_entity_id" TEXT,
  "read_status" TEXT,
  "po_id" TEXT,
  "open_impact_count" INTEGER,
  "ack_id" TEXT,
  "change_request_id" TEXT,
  "source_event_id" TEXT,
  "channel" TEXT,
  "status" TEXT,
  "title" TEXT,
  "body" TEXT,
  "scheduled_at" TEXT,
  "sent_at" TEXT,
  "delivered_at" TEXT,
  "retry_count" INTEGER,
  "last_error" TEXT,
  "created_at" TEXT,
  FOREIGN KEY ("po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("ack_id") REFERENCES "acknowledgements"("ack_id"),
  FOREIGN KEY ("change_request_id") REFERENCES "change_requests"("change_request_id")
);

CREATE TABLE "notification_recipient" (
  "notification_id" TEXT,
  "actor_role" TEXT,
  "recipient_actor_id" TEXT,
  PRIMARY KEY ("notification_id", "actor_role"),
  FOREIGN KEY ("notification_id") REFERENCES "notifications"("notification_id"),
  FOREIGN KEY ("recipient_actor_id") REFERENCES "actors"("actor_id")
);

CREATE TABLE "entity_event" (
  "event_id" TEXT PRIMARY KEY,
  "entity_type" TEXT,
  "entity_id" TEXT,
  "event_type" TEXT,
  "event_timestamp" TEXT,
  "actor_role" TEXT,
  "actor_id" TEXT,
  "payload_json" TEXT,
  "previous_state" TEXT,
  "new_state" TEXT,
  "target_supplier_id" TEXT,
  "target_po_id" TEXT,
  "target_po_line_id" TEXT,
  "target_ack_id" TEXT,
  "target_promise_date_id" TEXT,
  "target_change_request_id" TEXT,
  "target_approval_id" TEXT,
  "target_inventory_plan_id" TEXT,
  "target_production_order_id" TEXT,
  "target_notification_id" TEXT,
  FOREIGN KEY ("target_po_id") REFERENCES "purchase_orders"("po_id"),
  FOREIGN KEY ("target_po_line_id") REFERENCES "po_lines"("po_line_id"),
  FOREIGN KEY ("target_ack_id") REFERENCES "acknowledgements"("ack_id"),
  FOREIGN KEY ("target_promise_date_id") REFERENCES "promise_dates"("promise_date_id"),
  FOREIGN KEY ("target_change_request_id") REFERENCES "change_requests"("change_request_id"),
  FOREIGN KEY ("target_approval_id") REFERENCES "approvals"("approval_id"),
  FOREIGN KEY ("target_inventory_plan_id") REFERENCES "inventory_plans"("inventory_plan_id"),
  FOREIGN KEY ("target_production_order_id") REFERENCES "production_orders"("production_order_id"),
  FOREIGN KEY ("target_notification_id") REFERENCES "notifications"("notification_id")
);

CREATE TABLE "actors" (
  "actor_id" TEXT PRIMARY KEY,
  "actor_role" TEXT,
  "actor_name" TEXT,
  "email" TEXT,
  "supplier_id" TEXT,
  "is_active" TEXT,
  "created_at" TEXT,
  FOREIGN KEY ("supplier_id") REFERENCES "suppliers"("supplier_id")
);

CREATE TABLE "carriers" (
  "carrier_id" TEXT PRIMARY KEY,
  "carrier_name" TEXT,
  "carrier_code" TEXT,
  "is_active" TEXT,
  "created_at" TEXT
);

CREATE TABLE "warehouses" (
  "warehouse_id" TEXT PRIMARY KEY,
  "warehouse_name" TEXT,
  "site_code" TEXT,
  "timezone" TEXT,
  "is_active" TEXT,
  "created_at" TEXT
);

CREATE TABLE "items" (
  "item_id" TEXT PRIMARY KEY,
  "item_name" TEXT,
  "default_uom" TEXT,
  "item_status" TEXT,
  "unit_price_min" TEXT,
  "unit_price_max" TEXT,
  "price_currency" TEXT,
  "created_at" TEXT
);































COMMIT;

PRAGMA foreign_keys = ON;

